        \n        # Each trigger is a potential P arrival\n        for on, off in on_off:\n            pick_time = start_time + (on / sr)\n            \n            # Add P pick\n            all_picks.append({\n                'station': station_id,\n                'time': pick_time,\n                'phase': 'P',\n                'probability': 0.7\n            })\n            \n            # Estimate S arrival (S-P time ~ distance/3.5 for regional events)\n            # Typical S-P time is 2-10 seconds for local events\n            # Add S pick 3 seconds after P (rough estimate)\n            s_time = pick_time + 3.0\n            all_picks.append({\n                'station': station_id,\n                'time': s_time,\n                'phase': 'S',\n                'probability': 0.6\n            })\n        \n        print(f\"{len(on_off)} events, {len(on_off)*2} picks\")\n        \n    except Exception as e:\n        print(f\"Error: {e}\")\n        continue\n\nprint(f\"\\nTotal picks: {len(all_picks)}\")\n\nif len(all_picks) == 0:\n    print(\"No picks! Creating empty results.\")\n    pd.DataFrame({'time': []}).to_csv('/root/results.csv', index=False)\n    exit(0)\n\npicks_df = pd.DataFrame(all_picks)\nprint(f\"P: {len(picks_df[picks_df['phase']=='P'])}, S: {len(picks_df[picks_df['phase']=='S'])}\")\n\n# Associate events\nprint(\"\\nAssociating events...\")\n\nmean_lat = np.mean([s['latitude'] for s in station_lookup.values()])\nmean_lon = np.mean([s['longitude'] for s in station_lookup.values()])\n\nvp, vs = 6.0, 6.0/1.75\n\norigin_times = []\nfor pick in all_picks:\n    if pick['station'] not in station_lookup:\n        continue\n    \n    s = station_lookup[pick['station']]\n    dist = np.sqrt((s['latitude']-mean_lat)**2 + (s['longitude']-mean_lon)**2) * 111.0\n    \n    tt = dist / (vp if pick['phase'] == 'P' else vs)\n    origin_times.append(pick['time'].timestamp - tt)\n\norigin_times_array = np.array(origin_times).reshape(-1, 1)\n\ndbscan = DBSCAN(eps=5